// 24-S5 acceptance: collaborator membership against PostgreSQL, in a
// throwaway schema (`src/test-support/database.ts`). The owner adds by email
// (an existing account at once, otherwise an invitation for 30 days),
// removes and revokes; an invitation is claimed by the account whose current
// email matches. Membership is keyed by account. Do not edit this file to
// match an implementation.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { Prisma } from '@prisma/client';
import { createGrid } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import { createTestDatabase, type TestDatabase } from '@/test-support/database';
import { editableBy } from './access';
import {
  addCollaborator, claimInvitations, listCollaborators, normalizeEmail, removeCollaborator, revokeInvitation,
} from './membership';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
}, 60_000);
afterAll(async () => { await db?.drop(); });

const DAY = 24 * 60 * 60 * 1000;
const NOW = new Date('2026-11-13T12:00:00Z');
let serial = 0;
const unique = (label: string) => `${label}-${++serial}`;

async function user(label: string, displayName: string | null = label) {
  const id = unique(label);
  await db.client.user.create({ data: { id, name: label, email: `${id}@members.example.test`, displayName } });
  return { id, email: `${id}@members.example.test` };
}
async function puzzle(builderId: string) {
  return (await db.client.puzzle.create({
    data: {
      builderId, title: 'Shared',
      grid: serializeGrid(createGrid({ cols: 3, rows: 3 })) as unknown as Prisma.InputJsonValue, hints: {},
    },
  })).id;
}
const members = async (puzzleId: string) =>
  (await db.client.puzzleCollaborator.findMany({ where: { puzzleId }, orderBy: { createdAt: 'asc' } })).map((row) => row.userId);
const invitations = async (puzzleId: string) =>
  (await db.client.puzzleInvitation.findMany({ where: { puzzleId }, orderBy: { email: 'asc' } }))
    .map(({ email, expiresAt }) => ({ email, expiresAt }));
const canEdit = async (userId: string, puzzleId: string) =>
  (await db.client.puzzle.count({ where: { id: puzzleId, AND: [editableBy(userId)] } })) === 1;

describe('24-S5-1 adding a collaborator', () => {
  it('normalizes addresses, and refuses malformed ones', () => {
    expect(normalizeEmail('  Jay.Doe@Example.TEST \n')).toBe('jay.doe@example.test');
    for (const bad of ['', '   ', 'jay', '@example.test', 'jay@', 'j ay@example.test', 'a@b@c', `${'x'.repeat(250)}@e.st`, 42, null]) {
      expect(normalizeEmail(bad), String(bad)).toBeNull();
    }
  });

  it('an address with an account becomes a collaborator at once, idempotently, in any case', async () => {
    const adam = await user('adam');
    const jay = await user('jay', 'Jay');
    const id = await puzzle(adam.id);

    const first = await addCollaborator(db.client, adam.id, { puzzleId: id, email: `  ${jay.email.toUpperCase()} ` }, { now: NOW });
    expect(first).toEqual({ status: 'added', userId: jay.id, username: 'Jay' });
    expect(await addCollaborator(db.client, adam.id, { puzzleId: id, email: jay.email }, { now: NOW }))
      .toEqual({ status: 'added', userId: jay.id, username: 'Jay' });
    expect(await members(id)).toEqual([jay.id]);
    expect(await invitations(id)).toEqual([]);
    expect(await canEdit(jay.id, id)).toBe(true);
  });

  it('any other address is stored as an invitation for 30 days, renewed when invited again', async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);

    expect(await addCollaborator(db.client, adam.id, { puzzleId: id, email: ' New.Person@Example.test ' }, { now: NOW }))
      .toEqual({ status: 'invited', email: 'new.person@example.test', expiresAt: new Date(NOW.getTime() + 30 * DAY) });
    const later = new Date(NOW.getTime() + 10 * DAY);
    expect(await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'new.person@example.test' }, { now: later }))
      .toEqual({ status: 'invited', email: 'new.person@example.test', expiresAt: new Date(later.getTime() + 30 * DAY) });
    expect(await invitations(id)).toEqual([{ email: 'new.person@example.test', expiresAt: new Date(later.getTime() + 30 * DAY) }]);
    expect(await members(id)).toEqual([]);
  });

  it('an account made after the invitation, then added, binds at once and its invitation goes', async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'late@members.example.test' }, { now: NOW });
    await db.client.user.create({ data: { id: unique('late'), name: 'Late', email: 'late@members.example.test', displayName: 'Late' } });

    const outcome = await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'LATE@members.example.test' }, { now: NOW });
    expect(outcome).toMatchObject({ status: 'added', username: 'Late' });
    expect(await invitations(id)).toEqual([]);
    expect(await members(id)).toHaveLength(1);
  });

  it("refuses the owner's own address, and malformed input", async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);
    expect(await addCollaborator(db.client, adam.id, { puzzleId: id, email: adam.email.toUpperCase() }, { now: NOW }))
      .toEqual({ status: 'refused', code: 'owner' });
    for (const input of [null, 'x', { puzzleId: id }, { puzzleId: id, email: 'nope' }, { puzzleId: 'bad id!', email: 'a@b.c' }]) {
      expect(await addCollaborator(db.client, adam.id, input, { now: NOW }), JSON.stringify(input)).toEqual({ status: 'invalid' });
    }
    expect(await members(id)).toEqual([]);
    expect(await invitations(id)).toEqual([]);
  });

  it('only the owner adds: a collaborator, a stranger and a missing puzzle get not-found, nothing written', async () => {
    const adam = await user('adam');
    const jay = await user('jay');
    const eve = await user('eve');
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: jay.email }, { now: NOW });

    for (const caller of [jay.id, eve.id]) {
      expect(await addCollaborator(db.client, caller, { puzzleId: id, email: 'someone@example.test' }, { now: NOW })).toEqual({ status: 'not-found' });
      expect(await addCollaborator(db.client, caller, { puzzleId: id, email: eve.email }, { now: NOW })).toEqual({ status: 'not-found' });
    }
    expect(await addCollaborator(db.client, adam.id, { puzzleId: 'missing', email: eve.email }, { now: NOW })).toEqual({ status: 'not-found' });
    expect(await members(id)).toEqual([jay.id]);
    expect(await invitations(id)).toEqual([]);
  });
});

describe('24-S5-2 claiming an invitation', () => {
  it('is claimed once by the account whose current email matches, in any case and spacing', async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);
    const other = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'claimer@example.test' }, { now: NOW });
    await addCollaborator(db.client, adam.id, { puzzleId: other, email: 'claimer@example.test' }, { now: NOW });
    const claimer = await user('claimer');
    expect(await canEdit(claimer.id, id)).toBe(false);

    expect(await claimInvitations(db.client, { id: claimer.id, email: ' Claimer@Example.TEST ' }, { now: NOW })).toBe(2);
    expect(await members(id)).toEqual([claimer.id]);
    expect(await members(other)).toEqual([claimer.id]);
    expect(await invitations(id)).toEqual([]);
    expect(await canEdit(claimer.id, id)).toBe(true);
    expect(await claimInvitations(db.client, { id: claimer.id, email: 'claimer@example.test' }, { now: NOW })).toBe(0);
    expect(await members(id)).toEqual([claimer.id]);
  });

  it('is not claimed by another address, nor once expired', async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'expiring@example.test' }, { now: NOW });
    const someone = await user('someone');

    expect(await claimInvitations(db.client, { id: someone.id, email: 'someone-else@example.test' }, { now: NOW })).toBe(0);
    expect(await claimInvitations(db.client, { id: someone.id, email: 'expiring@example.test' }, { now: new Date(NOW.getTime() + 30 * DAY + 1) })).toBe(0);
    expect(await members(id)).toEqual([]);
    expect(await canEdit(someone.id, id)).toBe(false);
  });

  it("never makes the owner a collaborator of their own puzzle", async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);
    await db.client.puzzleInvitation.create({ data: { puzzleId: id, email: 'owner-alias@example.test', expiresAt: new Date(NOW.getTime() + DAY) } });

    expect(await claimInvitations(db.client, { id: adam.id, email: 'owner-alias@example.test' }, { now: NOW })).toBe(0);
    expect(await members(id)).toEqual([]);
  });

  it('concurrent claims make one membership', async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'racer@example.test' }, { now: NOW });
    const racer = await user('racer');

    const counts = await Promise.all(Array.from({ length: 5 }, () =>
      claimInvitations(db.client, { id: racer.id, email: 'racer@example.test' }, { now: NOW })));
    expect(counts.reduce((sum, count) => sum + count, 0)).toBe(1);
    expect(await members(id)).toEqual([racer.id]);
    expect(await invitations(id)).toEqual([]);
  });

  it('a revoked invitation can’t be claimed', async () => {
    const adam = await user('adam');
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'revoked@example.test' }, { now: NOW });
    expect(await revokeInvitation(db.client, adam.id, { puzzleId: id, email: ' REVOKED@example.test' })).toEqual({ status: 'revoked' });
    const someone = await user('revokee');

    expect(await claimInvitations(db.client, { id: someone.id, email: 'revoked@example.test' }, { now: NOW })).toBe(0);
    expect(await members(id)).toEqual([]);
  });
});

describe('24-S5-3 removing, revoking and listing', () => {
  it('only the owner removes; one membership goes, the others and the puzzle stay', async () => {
    const adam = await user('adam');
    const jay = await user('jay');
    const kim = await user('kim');
    const id = await puzzle(adam.id);
    const elsewhere = await puzzle(adam.id);
    for (const email of [jay.email, kim.email]) await addCollaborator(db.client, adam.id, { puzzleId: id, email }, { now: NOW });
    await addCollaborator(db.client, adam.id, { puzzleId: elsewhere, email: jay.email }, { now: NOW });

    expect(await removeCollaborator(db.client, kim.id, { puzzleId: id, userId: jay.id })).toEqual({ status: 'not-found' });
    expect(await members(id)).toEqual([jay.id, kim.id]);

    expect(await removeCollaborator(db.client, adam.id, { puzzleId: id, userId: jay.id })).toEqual({ status: 'removed' });
    expect(await removeCollaborator(db.client, adam.id, { puzzleId: id, userId: jay.id })).toEqual({ status: 'removed' });
    expect(await members(id)).toEqual([kim.id]);
    expect(await members(elsewhere)).toEqual([jay.id]);
    expect(await canEdit(jay.id, id)).toBe(false);
    expect(await db.client.puzzle.count({ where: { id } })).toBe(1);
    expect(await removeCollaborator(db.client, adam.id, { puzzleId: id })).toEqual({ status: 'invalid' });
  });

  it('only the owner revokes; revoking twice is still revoked', async () => {
    const adam = await user('adam');
    const jay = await user('jay');
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: jay.email }, { now: NOW });
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'pending@example.test' }, { now: NOW });

    expect(await revokeInvitation(db.client, jay.id, { puzzleId: id, email: 'pending@example.test' })).toEqual({ status: 'not-found' });
    expect(await invitations(id)).toHaveLength(1);
    expect(await revokeInvitation(db.client, adam.id, { puzzleId: id, email: 'pending@example.test' })).toEqual({ status: 'revoked' });
    expect(await revokeInvitation(db.client, adam.id, { puzzleId: id, email: 'pending@example.test' })).toEqual({ status: 'revoked' });
    expect(await invitations(id)).toEqual([]);
    expect(await revokeInvitation(db.client, adam.id, { puzzleId: id, email: 'not an address' })).toEqual({ status: 'invalid' });
  });

  it('lists collaborators by username and unexpired invitations by email, never a collaborator’s email', async () => {
    const adam = await user('adam');
    const jay = await user('jay', 'Jay');
    const blank = await user('blank', null);
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: jay.email }, { now: NOW });
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: blank.email }, { now: new Date(NOW.getTime() + 1) });
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'fresh@example.test' }, { now: NOW });
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: 'stale@example.test' }, { now: new Date(NOW.getTime() - 31 * DAY) });
    await db.client.user.update({ where: { id: jay.id }, data: { email: 'jay-new@example.test' } });

    const listed = await listCollaborators(db.client, adam.id, { puzzleId: id }, { now: NOW });
    expect(listed).toEqual({
      status: 'ok',
      collaborators: [{ userId: jay.id, username: 'Jay' }, { userId: blank.id, username: null }],
      invitations: [{ email: 'fresh@example.test', expiresAt: new Date(NOW.getTime() + 30 * DAY) }],
    });
    expect(JSON.stringify(listed)).not.toContain('jay-new');
    expect(JSON.stringify(listed)).not.toContain(jay.email);
    expect(await listCollaborators(db.client, jay.id, { puzzleId: id }, { now: NOW })).toEqual({ status: 'not-found' });
    expect(await listCollaborators(db.client, adam.id, { puzzleId: '' }, { now: NOW })).toEqual({ status: 'invalid' });
  });

  it('changing an email or username never removes access', async () => {
    const adam = await user('adam');
    const jay = await user('jay');
    const id = await puzzle(adam.id);
    await addCollaborator(db.client, adam.id, { puzzleId: id, email: jay.email }, { now: NOW });

    await db.client.user.update({ where: { id: jay.id }, data: { email: 'renamed@example.test', displayName: 'Someone Else' } });
    expect(await canEdit(jay.id, id)).toBe(true);
    expect(await claimInvitations(db.client, { id: jay.id, email: 'renamed@example.test' }, { now: NOW })).toBe(0);
    expect(await members(id)).toEqual([jay.id]);
  });
});
